// The customer rates a resolved ticket from 1 to 5, once. A ticket of another organisation looks like no ticket at all.
// A low score tells the owning agent by email.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket; only a resolved ticket can be rated`);
  const rated = store.rateTicketOnce(id, { score, at: now.toISOString() });
  if (!rated) throw new Error('this ticket has already been rated');
  if (score <= LOW_SCORE && rated.owner_id) notifyAgent(store, rated.owner_id, { type: 'ticket_rated_low', ticketId: id, score });
  return getMyTicket(store, customer, id);
}
```

