'use strict';
// Nightly. Writes exports/csat-weekly.json: for each agent, how many ratings their tickets received in the past seven
// days and the average score. A ticket counts for its current owner; a ticket without an owner counts for no one.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function summarise(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.csat_score == null || !t.owner_id) continue;
    const ratedAt = new Date(t.csat_rated_at).getTime();
    if (ratedAt < since || ratedAt > now.getTime()) continue;
    const s = byAgent.get(t.owner_id) || { sum: 0, ratings: 0 };
    s.sum += t.csat_score;
    s.ratings += 1;
    byAgent.set(t.owner_id, s);
  }
  return [...byAgent.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agent_id, s]) => ({ agent_id, ratings: s.ratings, average: Math.round((s.sum / s.ratings) * 100) / 100 }));
}

function csatSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const agents = summarise(store, { now });
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'csat-weekly.json');
  fs.writeFileSync(file, JSON.stringify({ generated_at: now.toISOString(), window_days: WINDOW_DAYS, agents }, null, 2) + '\n');
  return { file, agents: agents.length };
}

module.exports = { csatSummary, summarise, WINDOW_DAYS };
```

